async fn parametros_de_paginacao_publicos_sao_estaveis() {
    let params = PaginationParams {
        page: Some(2),
        per_page: Some(50),
        pagination: Some("offset".into()),
        order_by: Some("id".into()),
        sort: Some("asc".into()),
