    let actual = filter_to_query(Some(&params));
    assert_eq!(
        actual,
        vec![
            ("order_by".to_string(), "id".to_string()),
            ("page".to_string(), "2".to_string()),
            ("pagination".to_string(), "offset".to_string()),
            ("per_page".to_string(), "50".to_string()),
            ("sort".to_string(), "asc".to_string()),
